import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    s = data[1]
    # L[i]: A's immediately before position i in the sequence with B's removed
    left = [0] * n
    run = 0
    for i in range(n):
        ch = s[i]
        if ch == 'B':
            left[i] = run
        elif ch == 'A':
            run += 1
        else:
            run = 0
    run = 0
    total = 0
    for i in range(n - 1, -1, -1):
        ch = s[i]
        if ch == 'B':
            total += max(left[i], run)
        elif ch == 'C':
            run += 1
        else:
            run = 0
    print(total)

